-- Sincronizar as sequências (se for PostgreSQL) para evitar erros de ID duplo futuro.
SELECT setval('workplaces_id_seq', (SELECT MAX(id) FROM workplaces));
SELECT setval('clients_id_seq', (SELECT MAX(id) FROM clients));
SELECT setval('workplace_clients_id_seq', (SELECT MAX(id) FROM workplace_clients));
SELECT setval('appointments_id_seq', (SELECT MAX(id) FROM appointments));